<?php
namespace App\Services;
use App\Enums\ShipmentStatus; use App\Models\Shipment; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use InvalidArgumentException;
class ShipmentStatusService {private const TRANSITIONS=['pending'=>['package_received','cancelled'],'package_received'=>['processing','cancelled'],'processing'=>['in_transit','held','delayed','cancelled'],'in_transit'=>['arrived_at_destination','delayed','held','returned'],'arrived_at_destination'=>['out_for_delivery','held','delayed','returned'],'out_for_delivery'=>['delivered','attempt_failed','delayed','returned'],'attempt_failed'=>['out_for_delivery','returned'],'delayed'=>['in_transit','out_for_delivery','returned','cancelled'],'held'=>['processing','in_transit','returned','cancelled']]; public function allowedTransitions(Shipment $shipment):array{if(in_array($shipment->status,[ShipmentStatus::DELIVERED,ShipmentStatus::CANCELLED],true))return [];return collect(self::TRANSITIONS[$shipment->status->value]??[])->map(fn($s)=>ShipmentStatus::from($s))->all();} public function changeStatus(Shipment $shipment,ShipmentStatus|string $newStatus,?string $location=null,?string $description=null,?Request $request=null):Shipment{$newStatus=$newStatus instanceof ShipmentStatus?$newStatus:ShipmentStatus::from($newStatus);$current=$shipment->status;if($current===$newStatus)throw new InvalidArgumentException('The shipment is already in this status.');$allowed=self::TRANSITIONS[$current->value]??[];if(!in_array($newStatus->value,$allowed,true))throw new InvalidArgumentException("Cannot change shipment from {$current->value} to {$newStatus->value}.");return DB::transaction(function()use($shipment,$newStatus,$location,$description,$request,$current){$old=$shipment->getOriginal();$shipment->update(['status'=>$newStatus,'current_location'=>$location?:$shipment->current_location,'delivered_at'=>$newStatus===ShipmentStatus::DELIVERED?now():$shipment->delivered_at]);$event=$shipment->events()->create(['status'=>$newStatus,'location'=>$location?:$shipment->current_location,'description'=>$description,'created_by'=>$request?->user()?->id]);if($request)app(AuditService::class)->record($request,'shipment.status_changed',$shipment,$old,$shipment->getAttributes());return $shipment->fresh(['customer','events','events.creator']);});}}
